const productSelect=`SELECT p.id,p.category_id,p.name,p.slug,p.description,p.product_type,p.price_paise,p.compare_at_paise,p.sku,CASE WHEN p.image_url LIKE 'data:image/%' THEN '' ELSE p.image_url END AS image_url,(p.image_url LIKE 'data:image/%') AS has_inline_image,p.image_alt,p.color,p.tag,p.sizes,p.stock,p.published,p.featured,p.created_at,p.updated_at,c.name AS category_name,COALESCE((SELECT json_agg(json_build_object('id',v.id,'sku',v.sku,'options',v.options,'pricePaise',COALESCE(v.price_paise,p.price_paise),'stock',v.stock)) FROM product_variants v WHERE v.product_id=p.id AND v.active=true),'[]'::json) AS variants,COALESCE((SELECT array_agg(DISTINCT v.options->>'Size' ORDER BY v.options->>'Size') FROM product_variants v WHERE v.product_id=p.id AND v.active=true AND v.options ? 'Size'),p.sizes) AS storefront_sizes,(SELECT json_build_object('average',ROUND(AVG(r.rating)::numeric,1),'count',COUNT(*)) FROM reviews r WHERE r.product_id=p.id AND r.approved=true) AS rating_summary FROM products p LEFT JOIN categories c ON c.id=p.category_id`;
async function normalizeProductImage(imageUrl){
 const match=imageUrl.match(/^data:image\/[a-z0-9.+-]+;base64,([A-Za-z0-9+/]+=*)$/i);
 if(!match)return imageUrl;
 const source=Buffer.from(match[1],'base64');
 if(source.length>30*1024*1024)throw Object.assign(new Error('Photos must be 30 MB or smaller.'),{status:413});
 let normalized;try{normalized=await sharp(source,{limitInputPixels:100000000}).rotate().resize({width:1000,height:1200,fit:'inside',withoutEnlargement:true}).jpeg({quality:78}).toBuffer();}catch(error){const readable=Object.assign(new Error('This photo could not be converted. Save it as JPG, PNG, WebP, AVIF, or TIFF and try again.'),{status:400});readable.cause=error;throw readable;}
 return `data:image/jpeg;base64,${normalized.toString('base64')}`;
}
const productImageCache=new Map();let productImageCacheBytes=0;const maxProductImageCacheBytes=32*1024*1024;
function cacheProductImage(id,imageUrl,version){
 const match=imageUrl.match(/^data:image\/(jpeg|webp);base64,([A-Za-z0-9+/]+=*)$/);if(!match)return;
 const body=Buffer.from(match[2],'base64');if(body.length>4*1024*1024)return;
 const previous=productImageCache.get(id);if(previous)productImageCacheBytes-=previous.body.length;
 while(productImageCacheBytes+body.length>maxProductImageCacheBytes&&productImageCache.size){const [oldId,oldImage]=productImageCache.entries().next().value;productImageCache.delete(oldId);productImageCacheBytes-=oldImage.body.length;}
 productImageCache.delete(id);productImageCache.set(id,{version,contentType:match[1]==='webp'?'image/webp':'image/jpeg',body});productImageCacheBytes+=body.length;
}
function sendProductImage(res,image){res.set({'Content-Type':image.contentType,'Cache-Control':'public, max-age=31536000, immutable','X-Content-Type-Options':'nosniff','ETag':`"${image.version}"`}).send(image.body);}
const productImageUrl=r=>`/api/products/${r.id}/image?v=${encodeURIComponent(new Date(r.updated_at||r.created_at).getTime())}`;
const mapProduct=r=>{const version=new Date(r.updated_at||r.created_at).getTime(),inlineImage=Boolean(r.has_inline_image)||r.image_url?.startsWith('data:image/');if(r.image_url?.startsWith('data:image/'))cacheProductImage(r.id,r.image_url,version);return {id:r.id,name:r.name,slug:r.slug,description:r.description,type:r.product_type,price:r.price_paise/100,pricePaise:r.price_paise,old:r.compare_at_paise?r.compare_at_paise/100:null,sku:r.sku||'',image:inlineImage?productImageUrl(r):r.image_url,imageAlt:r.image_alt,color:r.color,tag:r.tag,category:r.category_name||'',categoryId:r.category_id,sizes:r.storefront_sizes||r.sizes,variants:r.variants||[],rating:r.rating_summary||{average:null,count:0},stock:r.stock,published:r.published,featured:r.featured,createdAt:r.created_at};};
const loadStorefront=async database=>{const [banners,collections,pages,settings]=await Promise.all([database.query('SELECT id,placement,title,subtitle,image_url AS "imageUrl",image_alt AS "imageAlt",cta_label AS "ctaLabel",cta_url AS "ctaUrl",display_order FROM banners WHERE active=true ORDER BY display_order'),database.query("SELECT c.id,c.name,c.slug,c.description,c.image_url AS \"imageUrl\",c.destination_url AS \"destinationUrl\",c.updated_at,COALESCE(array_agg(cp.product_id) FILTER(WHERE cp.product_id IS NOT NULL),'{}') AS product_ids FROM collections c LEFT JOIN collection_products cp ON cp.collection_id=c.id WHERE c.published=true GROUP BY c.id ORDER BY c.display_order"),database.query('SELECT slug,title,body,updated_at FROM content_pages WHERE published=true ORDER BY slug'),database.query('SELECT key,value FROM store_settings')]);return {banners:banners.rows,collections:collections.rows.map(c=>({...c,imageUrl:c.imageUrl.startsWith('data:image/')?`/api/collections/${c.id}/image?v=${new Date(c.updated_at).getTime()}`:c.imageUrl})),pages:pages.rows,settings:Object.fromEntries(settings.rows.map(row=>[row.key,row.value]))};};
const mapHomepageReview=r=>({id:r.id,customerName:r.customer_name,rating:r.rating,body:r.body,productName:r.product_name,image:r.image_url.startsWith('data:image/')?productImageUrl({id:r.product_id,updated_at:r.updated_at,created_at:r.product_created_at}):r.image_url});

