app.get('/api/products',asyncRoute(async(req,res)=>{const values=[];let sql=`${productSelect} WHERE p.published=true`;if(req.query.category){values.push(String(req.query.category).slice(0,100));sql+=` AND c.slug=$${values.length}`;}if(req.query.q){values.push(`%${String(req.query.q).slice(0,100)}%`);sql+=` AND (p.name ILIKE $${values.length} OR p.product_type ILIKE $${values.length} OR p.color ILIKE $${values.length})`;}const sort=req.query.sort==='price_asc'?'p.price_paise ASC':req.query.sort==='price_desc'?'p.price_paise DESC':'p.featured DESC,p.created_at DESC';sql+=` ORDER BY ${sort} LIMIT 100`;const {rows}=await pool.query(sql,values);res.json(rows.map(mapProduct));}));
app.get('/api/products/:id/image',asyncRoute(async(req,res)=>{
  const requestedVersion=Number(req.query.v),cached=productImageCache.get(req.params.id);
  if(cached&&cached.version===requestedVersion)return sendProductImage(res,cached);
  const {rows}=await pool.query('SELECT image_url FROM products WHERE id=$1',[req.params.id]);
  const image=rows[0]?.image_url||'';
  const match=image.match(/^data:image\/(jpeg|webp);base64,([A-Za-z0-9+/]+=*)$/);
  if(!match)return res.status(404).end();
  const responseImage={version:requestedVersion,contentType:match[1]==='webp'?'image/webp':'image/jpeg',body:Buffer.from(match[2],'base64')};
  cacheProductImage(req.params.id,image,requestedVersion);
  return sendProductImage(res,responseImage);
}));
