app.get('/api/account',customerAuth,asyncRoute(async(req,res)=>{
  const [customer,orders,addresses]=await Promise.all([
    pool.query('SELECT id,name,phone,$2::text AS email FROM customers WHERE auth_user_id=$1',[req.customerAuth.id,req.customerAuth.email]),
    pool.query(`SELECT o.id,o.order_number,o.status,o.payment_status,o.payment_method,o.total_paise,o.refunded_paise,o.tracking_number,o.courier,o.created_at,o.updated_at,o.address,COALESCE(json_agg(json_build_object('id',i.id,'productId',i.product_id,'name',i.product_name,'image',i.image_url,'size',i.size,'quantity',i.quantity,'unitPricePaise',i.unit_price_paise)) FILTER(WHERE i.id IS NOT NULL),'[]'::json) AS items,COALESCE((SELECT json_agg(json_build_object('id',r.id,'type',r.request_type,'itemId',r.order_item_id,'reason',r.reason,'comments',r.comments,'status',r.status,'decisionReason',r.decision_reason,'requestedAt',r.requested_at,'updatedAt',r.updated_at) ORDER BY r.requested_at DESC) FROM customer_order_requests r WHERE r.order_id=o.id),'[]'::json) AS requests,COALESCE((SELECT json_agg(json_build_object('id',f.id,'amountPaise',f.amount_paise,'status',f.status,'createdAt',f.created_at,'updatedAt',f.updated_at) ORDER BY f.created_at DESC) FROM refund_transactions f WHERE f.order_id=o.id),'[]'::json) AS refunds FROM orders o JOIN customers c ON c.id=o.customer_id LEFT JOIN order_items i ON i.order_id=o.id WHERE c.auth_user_id=$1 OR ($3::boolean AND $2::text IS NOT NULL AND lower(c.email)=lower($2)) GROUP BY o.id ORDER BY o.created_at DESC LIMIT 100`,[req.customerAuth.id,req.customerAuth.email,req.customerAuth.emailVerified]),
    pool.query('SELECT id,label,recipient_name,phone,line1,line2,city,state,pincode,is_default,created_at FROM customer_addresses WHERE auth_user_id=$1 ORDER BY is_default DESC,created_at DESC',[req.customerAuth.id]),
  ]);
  const [wishlist,notifications]=await Promise.all([
    pool.query('SELECT w.product_id,p.name,p.slug,p.image_url,p.price_paise,p.compare_at_paise,p.color,p.tag,p.stock,p.product_type FROM customer_wishlists w JOIN products p ON p.id=w.product_id WHERE w.auth_user_id=$1 AND p.published=true ORDER BY w.created_at DESC',[req.customerAuth.id]),
    pool.query('SELECT id,title,body,order_id,created_at,read_at FROM customer_notifications WHERE auth_user_id=$1 ORDER BY created_at DESC LIMIT 100',[req.customerAuth.id]),
  ]);
  res.json({profile:customer.rows[0]||{name:req.customerAuth.name,email:req.customerAuth.email,phone:''},orders:orders.rows,addresses:addresses.rows,wishlist:wishlist.rows.map(row=>row.product_id),wishlistProducts:wishlist.rows.map(row=>({id:row.product_id,name:row.name,slug:row.slug,image:row.image_url,pricePaise:row.price_paise,compareAtPaise:row.compare_at_paise,color:row.color,tag:row.tag,stock:row.stock,type:row.product_type})),notifications:notifications.rows});
}));
