app.put('/api/account/addresses/:id',customerAuth,asyncRoute(async(req,res)=>{const address=addressInput.parse(req.body);const client=await pool.connect();let rows;try{await client.query('BEGIN');if(req.body.isDefault)await client.query('UPDATE customer_addresses SET is_default=false WHERE auth_user_id=$1',[req.customerAuth.id]);({rows}=await client.query('UPDATE customer_addresses SET label=$3,recipient_name=$4,phone=$5,line1=$6,line2=$7,city=$8,state=$9,pincode=$10,is_default=CASE WHEN $11 THEN true ELSE is_default END,updated_at=now() WHERE id=$1 AND auth_user_id=$2 RETURNING id,label,recipient_name,phone,line1,line2,city,state,pincode,is_default,created_at', [req.params.id,req.customerAuth.id,address.label,address.recipientName,address.phone,address.line1,address.line2,address.city,address.state,address.pincode,Boolean(req.body.isDefault)]));if(!rows[0])throw Object.assign(new Error('Saved address not found.'),{status:404});await client.query('COMMIT');}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}res.json(rows[0]);}));
