app.post('/api/account/orders/:id/requests',customerAuth,asyncRoute(async(req,res)=>{const d=z.object({type:z.enum(['cancellation','return','exchange']),itemId:z.string().uuid().optional(),reason:z.string().trim().min(3).max(300),comments:z.string().trim().max(1000).default('')}).parse(req.body);const client=await pool.connect();let created;try{await client.query('BEGIN');const result=await client.query('SELECT o.id,o.status,o.delivered_at,c.auth_user_id FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.id=$1 AND (c.auth_user_id=$2 OR ($3::boolean AND $4::text IS NOT NULL AND lower(c.email)=lower($4))) FOR UPDATE OF o',[req.params.id,req.customerAuth.id,req.customerAuth.emailVerified,req.customerAuth.email]);const order=result.rows[0];if(!order)throw Object.assign(new Error('Order not found.'),{status:404});if(d.type==='cancellation'&&!['pending_payment','confirmed','processing'].includes(order.status))throw Object.assign(new Error('This order is no longer eligible for a cancellation request.'),{status:409});if(d.type!=='cancellation'&&order.status!=='delivered')throw Object.assign(new Error('Return or exchange requests are available only after delivery.'),{status:409});let itemId=null;if(d.type!=='cancellation'){if(!d.itemId)throw Object.assign(new Error('Choose the item for this request.'),{status:400});const item=await client.query('SELECT id FROM order_items WHERE id=$1 AND order_id=$2',[d.itemId,order.id]);if(!item.rows[0])throw Object.assign(new Error('That item is not part of this order.'),{status:400});itemId=d.itemId;}const policy=await client.query("SELECT value->>'returnsDays' AS days FROM store_settings WHERE key='content'");const days=Math.max(0,Math.min(90,Number(policy.rows[0]?.days||7)));if(d.type!=='cancellation'&&(!order.delivered_at||Date.now()-new Date(order.delivered_at).getTime()>days*86400000))throw Object.assign(new Error('The store return window has passed or delivery date is unavailable. Please contact support if you need help.'),{status:409});const {rows}=await client.query('INSERT INTO customer_order_requests(order_id,order_item_id,request_type,reason,comments) VALUES($1,$2,$3,$4,$5) RETURNING id,request_type,status,requested_at',[order.id,itemId,d.type,d.reason,d.comments]);created=rows[0];await audit(client,req.customerAuth.email||'customer','customer_request','order',order.id,{requestId:created.id,type:d.type});await client.query('COMMIT');}catch(error){await client.query('ROLLBACK');if(error.code==='23505')throw Object.assign(new Error('A similar request is already being reviewed for this order item.'),{status:409});throw error;}finally{client.release();}res.status(201).json(created);}));
