app.post('/api/admin/login',asyncRoute(async(req,res)=>{const body=z.object({email:z.string().email().max(254),password:z.string().min(8).max(200)}).parse(req.body);if(!process.env.ADMIN_EMAIL||!process.env.ADMIN_PASSWORD_HASH)return res.status(503).json({error:'Set ADMIN_EMAIL and ADMIN_PASSWORD_HASH on the server first.'});const emailMatch=body.email.toLowerCase()===process.env.ADMIN_EMAIL.toLowerCase();const valid=emailMatch&&await bcrypt.compare(body.password,process.env.ADMIN_PASSWORD_HASH);if(!valid)return res.status(401).json({error:'Email or password is incorrect.'});const token=jwt.sign({role:'admin',email:body.email.toLowerCase()},jwtSecret,{expiresIn:'8h',issuer:'thara-api',audience:'thara-admin'});res.json({token,email:body.email.toLowerCase(),expiresIn:28800});}));
