app.get('/api/admin/reports/sales.csv',adminAuth,asyncRoute(async(_req,res)=>{
 const {rows}=await pool.query("SELECT order_number,created_at,customer_name,phone,email,status,payment_status,payment_method,subtotal_paise,discount_paise,shipping_paise,total_paise,courier,tracking_number FROM orders ORDER BY created_at DESC");
 const columns=[['Order number','order_number'],['Order date','created_at'],['Customer name','customer_name'],['Phone','phone'],['Email','email'],['Order status','status'],['Payment status','payment_status'],['Payment method','payment_method'],['Subtotal (₹)','subtotal_paise',true],['Discount (₹)','discount_paise',true],['Shipping (₹)','shipping_paise',true],['Total (₹)','total_paise',true],['Courier','courier'],['Tracking number','tracking_number']];
 const csvCell=value=>{let text=String(value??'');if('=+@-'.includes(text[0])||text.charCodeAt(0)===9||text.charCodeAt(0)===13)text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
 const csv=[columns.map(([label])=>csvCell(label)).join(','),...rows.map(row=>columns.map(([,key,rupees])=>csvCell(rupees?(Number(row[key]||0)/100).toFixed(2):key==='created_at'?new Date(row[key]).toISOString():row[key])).join(','))].join(String.fromCharCode(13,10));
 res.set({'Content-Type':'text/csv; charset=utf-8','Content-Disposition':'attachment; filename="thara-sales-report.csv"','Cache-Control':'no-store'}).send('\uFEFF'+csv);
}));
