app.post('/api/admin/cms/collections/initialize-homepage',adminAuth,asyncRoute(async(_req,res)=>{const defaults=[{name:'Quad Sets',slug:'quad-sets',description:'Easy matching',imageUrl:'https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=640&q=78',category:'sets'},{name:'3-Piece Sets',slug:'three-piece-sets',description:'Ready, beautifully',imageUrl:'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=640&q=78',category:'sets'},{name:'Tops',slug:'tops',description:'Everyday favourites',imageUrl:'https://images.unsplash.com/photo-1598554747436-c9293d6a588f?auto=format&fit=crop&w=640&q=78',category:'tops'},{name:'Kurtis',slug:'kurtis',description:'A little tradition',imageUrl:'https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=640&q=78',category:'kurtas'},{name:'Maxi Dresses',slug:'maxi-dresses',description:'Made to move',imageUrl:'https://images.unsplash.com/photo-1595777457583-95e059d581b8?auto=format&fit=crop&w=640&q=78',category:'dresses'}];const client=await pool.connect();const created=[];try{await client.query('BEGIN');for(const [index,item] of defaults.entries()){const inserted=await client.query('INSERT INTO collections(name,slug,description,image_url,published,display_order) VALUES($1,$2,$3,$4,true,$5) ON CONFLICT(slug) DO NOTHING RETURNING id',[item.name,item.slug,item.description,item.imageUrl,index]);if(!inserted.rows[0])continue;const products=await client.query('SELECT p.id FROM products p JOIN categories c ON c.id=p.category_id WHERE p.published=true AND lower(c.slug)=$1 ORDER BY p.featured DESC,p.created_at DESC',[item.category]);for(const [order,product] of products.rows.entries())await client.query('INSERT INTO collection_products(collection_id,product_id,display_order) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[inserted.rows[0].id,product.id,order]);created.push(inserted.rows[0].id);}await client.query("INSERT INTO store_settings(key,value) VALUES('homepageCategoriesManaged','true'::jsonb) ON CONFLICT(key) DO UPDATE SET value='true'::jsonb,updated_at=now()");await audit(client,_req.admin.email,'initialize','homepage_collections',null,{createdCount:created.length});await client.query('COMMIT');res.json({createdCount:created.length});}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}));
