app.patch('/api/admin/customer-requests/:id',adminAuth,asyncRoute(async(req,res)=>{const d=z.object({status:z.enum(['under_review','approved','rejected','pickup_arranged','received','refund_processing','completed']),decisionReason:z.string().trim().max(1000).default('')}).parse(req.body);const transitions={requested:['under_review','approved','rejected','refund_processing'],under_review:['approved','rejected','refund_processing'],approved:['pickup_arranged','received','rejected','refund_processing'],pickup_arranged:['received','rejected','refund_processing'],received:['refund_processing','completed'],refund_processing:['completed'],rejected:[],completed:[]};const client=await pool.connect();try{await client.query('BEGIN');const current=await client.query('SELECT r.id,r.order_id,r.request_type,r.status,o.order_number,c.auth_user_id FROM customer_order_requests r JOIN orders o ON o.id=r.order_id JOIN customers c ON c.id=o.customer_id WHERE r.id=$1 FOR UPDATE OF r',[req.params.id]);if(!current.rows[0])throw Object.assign(new Error('Customer request not found.'),{status:404});if(!transitions[current.rows[0].status]?.includes(d.status))throw Object.assign(new Error(`Cannot move this request from ${current.rows[0].status} to ${d.status}.`),{status:409});const {rows}=await client.query('UPDATE customer_order_requests SET status=$2,decision_reason=$3,updated_at=now() WHERE id=$1 RETURNING id,order_id,request_type,status,decision_reason',[req.params.id,d.status,d.decisionReason]);await createCustomerNotification(client,current.rows[0].auth_user_id,`${current.rows[0].request_type} update · ${current.rows[0].order_number}`,`Your ${current.rows[0].request_type} request is now ${d.status.replaceAll('_',' ')}.${d.decisionReason?` ${d.decisionReason}`:''}`,current.rows[0].order_id);await audit(client,req.admin.email,'update_customer_request',rows[0].request_type,rows[0].id,{status:d.status,decisionReason:d.decisionReason});await client.query('COMMIT');res.json(rows[0]);}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}}));
app.patch('/api/admin/orders/:id',adminAuth,asyncRoute(async(req,res)=>{const d=z.object({status:z.enum(['confirmed','processing','shipped','delivered','cancelled','return_requested']),trackingNumber:z.string().max(100).optional(),courier:z.string().max(100).optional()}).parse(req.body);const client=await pool.connect();try{await client.query('BEGIN');const previous=await client.query('SELECT o.id,o.status,o.payment_status,o.order_number,o.tracking_number,o.courier,c.auth_user_id FROM orders o LEFT JOIN customers c ON c.id=o.customer_id WHERE o.id=$1 FOR UPDATE OF o',[req.params.id]);if(!previous.rows[0]){await client.query('ROLLBACK');return res.status(404).json({error:'Order not found.'});}if(d.status==='cancelled'&&previous.rows[0].payment_status==='paid'){throw Object.assign(new Error('This order has a captured payment. Initiate and verify its refund before cancelling it.'),{status:409});}const {rows}=await client.query("UPDATE orders SET status=$2,tracking_number=$3,courier=$4,delivered_at=CASE WHEN $2='delivered' THEN COALESCE(delivered_at,now()) ELSE delivered_at END,updated_at=now() WHERE id=$1 RETURNING *",[req.params.id,d.status,d.trackingNumber||null,d.courier||null]);if(d.status==='cancelled'&&previous.rows[0].status!=='cancelled')await releaseReservedStock(client,req.params.id,'Order cancelled; stock released');const trackingChanged=(d.trackingNumber||null)!==previous.rows[0].tracking_number||(d.courier||null)!==previous.rows[0].courier;if(previous.rows[0].status!==d.status||trackingChanged)await createCustomerNotification(client,previous.rows[0].auth_user_id,`Order update · ${previous.rows[0].order_number}`,`Your order is now ${d.status.replaceAll('_',' ')}.${d.trackingNumber?` ${d.courier||'Courier'} tracking: ${d.trackingNumber}.`:''}`,req.params.id);await audit(client,req.admin.email,'update_status','order',req.params.id,{status:d.status});await client.query('COMMIT');const order=rows[0];await sendNotice(order.email,`Tara order ${order.order_number}: ${order.status}`,`Hi ${order.customer_name}, your order ${order.order_number} is now ${order.status}.${order.tracking_number?` Tracking: ${order.tracking_number}.`:''}`);res.json(order);}catch(e){await client.query('ROLLBACK');throw e;}finally{client.release();}}));
