app.use(express.static(frontendDirectory,{index:false,maxAge:process.env.NODE_ENV==='production'?'1h':0}));
app.get(/^(?!\/api(?:\/|$)).*/,(_req,res,next)=>res.sendFile(path.join(frontendDirectory,'index.html'),error=>{if(error)next(error);}));
app.use((err,req,res,_next)=>{if(err instanceof z.ZodError)return res.status(400).json({error:'Please check the submitted details.',details:err.issues.map(i=>({path:i.path.join('.'),message:i.message}))});console.error('Unhandled API error:',err.code||'UNKNOWN',err.message);if(err.code==='28P01')return res.status(503).json({error:'Neon rejected the database password. Update DATABASE_URL using the current production connection string.'});if(isTransientDatabaseError(err)||/connection timeout|connection terminated due to connection timeout/i.test(err.message||''))return res.status(503).json({error:'The store database is temporarily unavailable. Your order was not placed. Please try again shortly.'});if(req.path==='/api/admin/products'||req.path.startsWith('/api/admin/products/')){if(err.code==='23505'){const uniqueField=String(err.constraint||err.message||'').toLowerCase();if(uniqueField.includes('sku'))return res.status(409).json({error:'That SKU is already in use. Leave the product SKU blank to generate one, or choose a unique SKU for each size variant.'});if(uniqueField.includes('slug'))return res.status(409).json({error:'That URL slug is already in use. Leave the slug blank to generate a unique one.'});return res.status(409).json({error:'A product field must be unique. Leave the product SKU and URL slug blank to generate unique values.'});}if(err.code==='23503')return res.status(400).json({error:'The selected category is no longer available. Choose a category again and retry.'});if(err.code==='42P01'||err.code==='42703')return res.status(503).json({error:'The product database needs an update before products can be saved. Please contact the store administrator.'});return res.status(err.status||500).json({error:err.status?err.message:'The server could not save this product. Check the server logs for the product-save error.'});}res.status(err.status||500).json({error:err.status?err.message:'Something went wrong. Please try again.'});});
const server=app.listen(port,()=>console.log(`Tara API listening on http://localhost:${port}`));
const expiryTimer=setInterval(expirePendingPayments,60_000);expiryTimer.unref();
async function shutdown(){clearInterval(expiryTimer);server.close();await pool.end();process.exit(0);}process.on('SIGINT',shutdown);process.on('SIGTERM',shutdown);

